package org.jfree.chart.renderer;

import java.awt.Color;
import java.awt.Paint;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class GrayPaintScale_getPaint_TriageGen0Test {

    @Test
    public void testGetPaint_ValueBelowLowerBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value = 5.0 (below lower bound)
        // v = max(5.0, 10.0) = 10.0
        // v = min(10.0, 20.0) = 10.0
        // g = (int) ((10.0 % 10.0) / (20.0 - 10.0) * 255.0) = (int) (0.0 / 10.0 * 255.0) = 0
        Paint paint = scale.getPaint(5.0);
        assertEquals(new Color(0, 0, 0), paint);
    }










}

