package org.jfree.chart.renderer;

import java.awt.Color;
import java.awt.Paint;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class GrayPaintScale_getPaint_TriageGen0Test {









    @Test
    public void testGetPaint_MidRangeValue() {
        double lower = 0.0;
        // To avoid division by zero or modulo zero issues in the provided logic, 
        // we use a non-zero lower bound.
        double upper = 100.0;
        double lowerBound = 10.0;
        GrayPaintScale scale = new GrayPaintScale(lowerBound, upper);

        // value = 60.0
        // v = 60.0
        // g = (int) ((60.0 % 10.0) / (100.0 - 10.0) * 255.0) 
        // g = (int) (0.0 / 90.0 * 255.0) = 0
        // Let's pick a value where (v % lowerBound) is not zero.

        // value = 15.0
        // v = 15.0
        // g = (int) ((15.0 % 10.0) / (100.0 - 10.0) * 255.0)
        // g = (int) (5.0 / 90.0 * 255.0) = (int) (0.0555 * 255) = (int) 14.166 = 14
        Paint paint = scale.getPaint(15.0);
        assertEquals(new Color(14, 14, 14), paint);
    }


}

package org.jfree.chart.renderer;

import java.awt.Color;
import java.awt.Paint;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class GrayPaintScale_getPaint_TriageGen0Test {











    @Test
    public void testGetPaint_MaxIntensity() {
        // To get g = 255:
        // (v % lower) / (upper - lower) * 255 = 255
        // (v % lower) / (upper - lower) = 1
        // v % lower = upper - lower

        // Example: lower = 10, upper = 15
        // v % 10 = 15 - 10 = 5
        // v = 15 works.
        double lower = 10.0;
        double upper = 15.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value = 15.0
        // v = 15.0
        // g = (int) ((15.0 % 10.0) / (15.0 - 10.0) * 255.0)
        // g = (int) (5.0 / 5.0 * 255.0) = 255
        Paint paint = scale.getPaint(15.0);
        assertEquals(new Color(255, 255, 255), paint);
    }
}
